PRAGMA foreign_keys = ON;

CREATE TABLE doctors (
	id INTEGER NOT NULL, 
	full_name VARCHAR(120) NOT NULL, 
	specialty VARCHAR(80) NOT NULL, 
	is_active BOOLEAN NOT NULL, 
	slot_minutes SMALLINT, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT ck_doctor_slot CHECK (slot_minutes IS NULL OR slot_minutes BETWEEN 5 AND 240)
);

CREATE TABLE patients (
	id INTEGER NOT NULL, 
	mrn VARCHAR(32) NOT NULL, 
	first_name VARCHAR(80) NOT NULL, 
	last_name VARCHAR(80) NOT NULL, 
	date_of_birth DATE, 
	phone VARCHAR(32), 
	preferred_language VARCHAR(8) NOT NULL, 
	is_vip BOOLEAN NOT NULL, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (mrn)
);

CREATE TABLE appointments (
	id INTEGER NOT NULL, 
	patient_id INTEGER NOT NULL, 
	doctor_id INTEGER NOT NULL, 
	starts_at DATETIME NOT NULL, 
	ends_at DATETIME NOT NULL, 
	status VARCHAR(16) NOT NULL, 
	reason VARCHAR(255), 
	checked_in_at DATETIME, 
	reminder_sent_at DATETIME, 
	version_id INTEGER NOT NULL, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT ck_appointment_order CHECK (starts_at < ends_at), 
	FOREIGN KEY(patient_id) REFERENCES patients (id) ON DELETE RESTRICT, 
	FOREIGN KEY(doctor_id) REFERENCES doctors (id) ON DELETE RESTRICT
);

CREATE INDEX ix_appointment_doctor_start ON appointments (doctor_id, starts_at);

CREATE INDEX ix_appointment_patient_start ON appointments (patient_id, starts_at);

CREATE INDEX ix_appointment_status_start ON appointments (status, starts_at);

CREATE TABLE doctor_shifts (
	id INTEGER NOT NULL, 
	doctor_id INTEGER NOT NULL, 
	weekday SMALLINT NOT NULL, 
	start_time TIME NOT NULL, 
	end_time TIME NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT ck_shift_weekday CHECK (weekday BETWEEN 0 AND 6), 
	CONSTRAINT ck_shift_order CHECK (start_time < end_time), 
	FOREIGN KEY(doctor_id) REFERENCES doctors (id) ON DELETE CASCADE
);

CREATE INDEX ix_shift_doctor_weekday ON doctor_shifts (doctor_id, weekday);

CREATE TABLE queue_tickets (
	id INTEGER NOT NULL, 
	service_date DATE NOT NULL, 
	number INTEGER NOT NULL, 
	patient_id INTEGER, 
	doctor_id INTEGER, 
	appointment_id INTEGER, 
	status VARCHAR(16) NOT NULL, 
	counter VARCHAR(32), 
	issued_at DATETIME NOT NULL, 
	called_at DATETIME, 
	served_at DATETIME, 
	finished_at DATETIME, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_ticket_day_number UNIQUE (service_date, number), 
	FOREIGN KEY(patient_id) REFERENCES patients (id) ON DELETE SET NULL, 
	FOREIGN KEY(doctor_id) REFERENCES doctors (id) ON DELETE SET NULL, 
	FOREIGN KEY(appointment_id) REFERENCES appointments (id) ON DELETE SET NULL
);

CREATE INDEX ix_ticket_day_status ON queue_tickets (service_date, status);
